// Manual date entry via keyboard: parse Enter‑key input
$selectDate.on('keyup', function(e) {
    if (e.key === 'Enter') {
        const inputVal = $(this).val().trim();
        if (inputVal) {
            const parsed = moment(inputVal, 'DD/MM/YYYY', true);
            if (parsed.isValid()) {
                App.Utils.UI.setDateTimePickerValue($selectDate, parsed.toDate());
                App.Http.Booking.getAvailableHours(parsed.format('YYYY-MM-DD'));
                App.Pages.Booking.updateConfirmFrame();
            }
        }
    }
});

